#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
	// your code goes here
	int t;
	cin >> t;
	while(t--){
	    
	    int n;
	    cin >> n;
	    
	    vector<ll> a(3*n);
	    for(ll &x : a)cin >> x;
	    
	    sort(a.rbegin(),a.rend());
	    
	    vector<ll> pref(3 * n + 1,0);
	    
	    for(int i = 0 ; i < 3*n;++i)pref[i+1] = pref[i] + a[i];
	    
	    auto calc = [&](int A , int B) -> ll{
	        int j = A + 2 * B;
	        int k = 3 * n -2 * A - B;
	        
	        return 2LL * pref[A] + pref[j] +3ll * pref[k];
};
	    
	    
	    ll ans = 0;
	    for(int A = 0; A <= n; ++A){
	        int M = n- A;
	        
	        if(M == 0){
	            ans = max(ans,calc(A,0));
	            continue;
	        }
	        
	        int lo = 0,hi = M-1;
	        
	        while(lo < hi){
	            int B = (lo + hi)/2;
	            
	            int j = A + 2 * B;
	            
	            int k = 3 * n -2 * A - B;
	            
	            ll delta = a[j] + a[j+1] - 3LL * a[k-1];
	            if(delta >= 0)lo = B+1;
	            else hi = B;
	        }
	        ans = max(ans , calc(A,0));
	        ans = max(ans,calc(A,M));
	        
	        for(int B : {lo -1,lo}){
	            if(B >= 0 && B <= M)ans= max(ans,calc(A,B));
	        }
	    }
	    
	    
	    cout << ans <<'\n';
	    
	}
return 0;
}
